begin;
select plan(22);
select has_table('private','catalog_video_r2_config','050 config singleton exists');
select has_table('private','catalog_video_r2_preferences','050 preferences exist');
select has_table('private','catalog_video_r2_copies','050 copies exist');
select has_table('private','catalog_video_r2_parts','050 parts exist');
select has_table('private','catalog_video_r2_uses','050 uses exist');
select has_table('private','catalog_video_r2_purges','050 tombstones exist');
select has_table('private','catalog_video_r2_journal','050 journal exists');
select has_table('public','team_catalog_video_r2_signals','050 public signals exist');
select has_column('private','catalog_publication_link_receipts','link_kind','publication link receipts carry the link kind');
select ok((select relrowsecurity and relforcerowsecurity from pg_class where oid='public.team_catalog_video_r2_signals'::regclass),'signals force RLS');
select ok((select count(*)=8 and bool_and(c.relrowsecurity) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='private' and c.relname like 'catalog_video_r2_%' and c.relkind='r'),'all eight private video tables enable RLS');
select ok(not has_table_privilege('authenticated','private.catalog_video_r2_copies','SELECT'),'object keys are not browser readable');
select ok(not has_table_privilege('service_role','private.catalog_video_r2_copies','SELECT'),'service role reaches copies only through RPC');
select ok(not has_function_privilege('authenticated','public.service_catalog_video_r2_claim(text)','EXECUTE'),'browser cannot claim worker copies');
select ok(not has_function_privilege('anon','public.service_catalog_video_r2_set_preference(uuid,uuid,boolean)','EXECUTE'),'anonymous cannot change the option');
select ok(not has_function_privilege('authenticated','public.service_catalog_video_r2_resolve(uuid,uuid,text,bigint,text,text)','EXECUTE'),'browser cannot resolve links');
select ok(has_function_privilege('service_role','public.service_record_catalog_publication_link(uuid,uuid,uuid,text,text,text)','EXECUTE'),'service role records receipts through the replaced RPC');
select is((select count(*)::int from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='service_record_catalog_publication_link'),1,'exactly one receipt RPC remains (no ambiguous overload)');
select ok((select pg_get_function_arguments(p.oid) like '%p_link_kind text DEFAULT ''drive''%' from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='service_record_catalog_publication_link'),'five-argument callers keep working through the default');
select ok(private.task_cleanup_coverage_verified(),'video metadata consumers retain the task cleanup reference fence');
select ok((select count(*)=2 from cron.job where jobname in ('soty-catalog-video-r2-claim','soty-catalog-video-r2-sweep')),'claim and sweep are scheduled');
select ok((select not enabled and policy_confirmed_at is null from private.catalog_video_r2_config),'feature starts disabled with the policy unconfirmed');
select * from finish();
rollback;
